{
  "case_id": "C09",
  "audience": "General public with secondary-school science literacy",
  "target_duration_s": 60,
  "beats": [
    {
      "beat": "Hook: two headlines, one trial",
      "narration": "A pill that cuts your risk of a heart attack by 42 percent. Or a pill that cuts it by less than two points. Same trial, same people, same result.",
      "on_screen": "Split screen. Left headline: 'Cuts risk by 42%'. Right headline: 'Cuts risk by 1.79 points'. Both stamped with the same trial ID, SYN-C09.",
      "claim_refs": ["SYN-C09:Background", "SYN-C09:Results"]
    },
    {
      "beat": "What the trial did",
      "narration": "Almost ten thousand adults aged 45 to 70 took part. None had heart disease or diabetes, and all were at low predicted risk. Half got a statin, half a placebo, for about four years. Nobody, not even the doctors, knew who got what.",
      "on_screen": "Simple icon grid splitting into two groups of 4,921. Captions: 'low baseline risk, median 5.1% over 10 years', '4.1 years', 'blinded, randomised'.",
      "claim_refs": ["SYN-C09:Abstract", "SYN-C09:Population", "SYN-C09:Methods"]
    },
    {
      "beat": "The raw counts",
      "narration": "Here is what happened. In the placebo group, 209 people had a major cardiovascular event: 4.25 percent. In the statin group, 121 people did: 2.46 percent. An independent committee checked every event without knowing who took what.",
      "on_screen": "Two bars side by side, placebo 4.25% and statin 2.46%, with the raw counts 209/4,921 and 121/4,921 labelled on each.",
      "claim_refs": ["SYN-C09:Abstract", "SYN-C09:Results", "SYN-C09:Methods"]
    },
    {
      "beat": "Relative versus absolute",
      "narration": "Now the arithmetic. Going from 4.25 down to 2.46 is a 42 percent relative reduction: the risk shrinks by nearly half. But the absolute gap is just 1.79 percentage points. Put another way, 56 people take the statin for four years so that one of them avoids an event.",
      "on_screen": "The same two bars. First a big '42% smaller' arrow between their tops, then the gap itself highlighted as '1.79 percentage points'. Finish on 56 figures, one of them highlighted.",
      "claim_refs": ["SYN-C09:Results"]
    },
    {
      "beat": "What to take away",
      "narration": "Neither number is a trick. The relative figure tells you how well the drug works. The absolute figure tells you what it is worth to you, given where your risk started. So ask for both, and ask how long the trial ran and what the side effects were.",
      "on_screen": "Checklist: 'Relative: how well it works. Absolute: what it is worth to me. How long? What harms?' Footnote: '4.1 years of follow-up; harms reported separately.'",
      "claim_refs": ["SYN-C09:Discussion", "SYN-C09:Limitations", "SYN-C09:Conclusion"]
    }
  ]
}
